import { CustomerCommunicationEntity } from '/app/src/customer/entities/customerCommunication.entity.js';
import { CustomerCommunicationChannel } from '/app/src/customer/entities/customerCommunication.interface.js';
import { CustomerCommunicationEmailProcessor } from '/app/src/customer/entities/customerCommunicationEmail.processor.js';

const bus = new CustomerCommunicationEntity();
bus.subscribe(CustomerCommunicationChannel.EMAIL, new CustomerCommunicationEmailProcessor());
const base = {
    subject: 's',
    fromName: 'Harbor Analytics',
    fromEmail: 'no-reply@meteringco.example',
    toEmail: 'ok@harbor-analytics.example',
    content: 'body',
    replyToName: 'Harbor Support',
    replyToEmail: 'support@meteringco.example',
};
const main = async () => {
    // unverified sender -> rejected
    bus.publish({ topic: CustomerCommunicationChannel.EMAIL, message: 'm', data: [{ ...base, fromEmail: 'nope@elsewhere.example', subject: 'unverified' }] });
    // suppressed recipient with an alternative entry that must NOT be used
    bus.publish({ topic: CustomerCommunicationChannel.EMAIL, message: 'm', data: [{ ...base, toEmail: 'bounced@lattice-robotics.example', subject: 'suppressed' }, { ...base, toEmail: 'fallback@lattice-robotics.example', subject: 'suppressed' }] });
    // empty payload
    bus.publish({ topic: CustomerCommunicationChannel.EMAIL, message: 'm', data: [] });
    // undefined payload
    bus.publish({ topic: CustomerCommunicationChannel.EMAIL, message: 'm', data: undefined as any });
    // no reply-to name
    bus.publish({ topic: CustomerCommunicationChannel.EMAIL, message: 'm', data: [{ ...base, replyToName: '', subject: 'no reply name' }] });
    // survives to the end
    bus.publish({ topic: CustomerCommunicationChannel.EMAIL, message: 'm', data: [{ ...base, subject: 'last one', html: true, content: '<html>hi</html>' }] });
    await new Promise((r) => setTimeout(r, 3000));
};
main();
EOF
